CREATE TABLE career_skills(id INTEGER PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, progress INTEGER NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), target_date TEXT, notes TEXT);
CREATE TABLE career_courses(id INTEGER PRIMARY KEY, name TEXT NOT NULL, provider TEXT, resource TEXT, skill_id INTEGER REFERENCES career_skills(id) ON DELETE SET NULL, progress INTEGER NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','in_progress','paused','completed')), due_date TEXT, notes TEXT);
CREATE TABLE career_applications(id INTEGER PRIMARY KEY, organization TEXT NOT NULL, role TEXT NOT NULL, resource TEXT, status TEXT NOT NULL DEFAULT 'saved' CHECK(status IN ('saved','applied','interview','offered','accepted','rejected','withdrawn')), applied_date TEXT, deadline TEXT, interview_at TEXT, notes TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX career_application_interviews ON career_applications(status,interview_at);
